import { forwardRef } from 'react'

import { Polymorphic } from '../../utils/PolymorphicUtils'
import { ContactData, ProfileData } from '../landing/landing-page'
import { Card } from '../shared/card/card'
import { Container } from '../shared/container/container'
import { Prose } from '../shared/prose/prose'
import { Section } from '../shared/section/section'

export type LegalPageData = {
  profile: ProfileData
  contacts: ContactData
  headline: string
  html: string
}

export type LegalPageProps = {
  data: LegalPageData
}

export const LegalPage = forwardRef(function LegalPage(
  { as: Component = 'main', data, className, ...props },
  ref,
) {
  return (
    <Component
      className={`relative z-10 flex-1 ${className ?? ''}`}
      {...props}
      ref={ref}
    >
      <Container>
        <Section headline={data.headline}>
          <Card size="lg">
            <Prose dangerouslySetInnerHTML={{ __html: data.html }}></Prose>
          </Card>
        </Section>
      </Container>
    </Component>
  )
}) as Polymorphic<'main', LegalPageProps>
