import { graphql, useStaticQuery } from 'gatsby'
import * as React from 'react'
import { Helmet } from 'react-helmet'
import { useTranslation } from 'react-i18next'

import { LegalPage } from '../components/legal/legal-page'
import { landing as landingDe } from '../data/landing/de'
import { landing as landingEn } from '../data/landing/en'
import { SupportedLanguages } from '../i18n/config'

type LegalNode = {
  relativeDirectory: SupportedLanguages
  childMarkdownRemark: {
    html: string
    frontmatter: {
      headline: string
    }
  }
}

type DataProps = {
  legalEntries: {
    nodes: LegalNode[]
  }
}

const ImprintPage = () => {
  const { i18n } = useTranslation()

  const currentLanguage = i18n.resolvedLanguage as keyof typeof dataByLanguage
  const data = useStaticQuery<DataProps>(graphql`
    query ImprintPageLegalQuery {
      legalEntries: allFile(
        filter: {
          sourceInstanceName: { eq: "legal" }
          name: { eq: "imprint" }
          relativeDirectory: { in: ["en", "de"] }
        }
      ) {
        nodes {
          relativeDirectory
          childMarkdownRemark {
            frontmatter {
              headline
            }
            html
          }
        }
      }
    }
  `)

  const legalByLanguage = data.legalEntries.nodes.reduce(
    (acc, node) => {
      acc[node.relativeDirectory] = node
      return acc
    },
    {} as Record<SupportedLanguages, LegalNode>,
  )

  const legal = legalByLanguage[currentLanguage]

  const dataByLanguage = {
    en: landingEn,
    de: landingDe,
  }

  const landingPageData = dataByLanguage[currentLanguage]

  return (
    <React.Fragment>
      <Helmet
        title={legal.childMarkdownRemark.frontmatter.headline}
        htmlAttributes={{ lang: currentLanguage === 'de' ? 'de-DE' : 'en-GB' }}
      />
      <LegalPage
        data={{
          headline: legal.childMarkdownRemark.frontmatter.headline,
          contacts: landingPageData.contacts,
          profile: landingPageData.profile,
          html: legal.childMarkdownRemark.html,
        }}
      />
    </React.Fragment>
  )
}

export default ImprintPage
