import { forwardRef } from 'react'

import { Polymorphic } from '../../../utils/PolymorphicUtils'

export const Prose = forwardRef(function Prose(
  { as: Component = 'div', className, ...props },
  ref,
) {
  const classNames = [
    'prose max-w-none dark:prose-invert text-ink-600 dark:text-ink-200 hyphens-auto',
    className,
  ]
    .filter(Boolean)
    .join(' ')

  return <Component className={classNames} {...props} ref={ref} />
}) as Polymorphic<'div'>
